    type State = ();
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let export = ctx.query();
        let export_clause = export.export_clause().ok()?;
        match export_clause {
            // `export * from "..."` and `export * as ns from "..."`
            AnyJsExportClause::JsExportFromClause(clause) => {
                // Allow type re-export, e.g. `export type * from "..."`
                if clause.type_token().is_some() {
                    return None;
                }
                Some(())
            }
            // `export { foo } from "..."`, `export { foo as bar } from "..."`, etc.
            AnyJsExportClause::JsExportNamedFromClause(clause) => {
                // Allow type re-export, e.g. `export type { foo } from "..."`
                if clause.type_token().is_some() {
                    return None;
                }
                Some(())
            }
            _ => None,
        }
    }

